// Convert: week from date, opponent + home from RESULTS ([week, away, aPts, home, hPts])
Object.entries(L).forEach(([name,[team,pos,rows]])=>{
  const tmOf={};
  const games=rows.map(([d,s,tm])=>{const T=tm||team;const w=WK(d);const g=RESULTS.find(r=>r[0]===w&&(r[1]===T||r[3]===T));
    if(!g){console.warn("no game",name,d);return null}if(tm)tmOf[w]=tm;const home=g[3]===T;return [w,home?g[1]:g[3],home?1:0,s]}).filter(Boolean);
  NFL_LOGS[name]=[team,pos,games];
  for(let i=REAL_LOGS.length-1;i>=0;i--)if(REAL_LOGS[i].player===name)REAL_LOGS.splice(i,1);
  REAL_LOGS.push(...RL(name,team,pos,games).map(l=>{if(tmOf[l.week])l.team=tmOf[l.week];return l}));
});
